struct Counter {
    value: i32,
}

fn increment(c: &mut Counter) {
    c.value = c.value + 1;
}

fn main() {
    let mut c = Counter { value: 0 };
    let mut i = 0;
    while i < 5 {
        increment(&mut c);
        i = i + 1;
    }
    print(c.value);
}

fn fib(n: i32) -> i32 {
    if n < 2 {
        return n;
    }
    return fib(n - 1) + fib(n - 2);
}

fn main() {
    print("fib(10) = ");
    print(fib(10));
}

